import gurobipy as gp
from gurobipy import GRB

try:
    # Extract data from pre-defined data dictionary with error handling
    n = data["num_customers"]
    start = data["start_location"]
    dist = data["distance_matrix"]

    # Validate data
    if n <= 0 or start < 1 or start > n:
        raise ValueError("Invalid customer count or start location")

    if len(dist) != n or any(len(row) != n for row in dist):
        raise ValueError("Invalid distance matrix dimensions")

    # Create model
    m = gp.Model("TSP")
    m.Params.OutputFlag = 0

    # Decision variables: x[i][j] = 1 if travel from i to j
    x = {}
    for i in range(n):
        for j in range(n):
            if i != j:
                x[i, j] = m.addVar(vtype=GRB.BINARY, name=f"x_{i+1}_{j+1}")

    # Subtour elimination variables (MTZ formulation)
    u = {}
    for i in range(n):
        u[i] = m.addVar(vtype=GRB.CONTINUOUS, lb=1, ub=n, name=f"u_{i+1}")

    # Fix u for start node (location 1)
    m.addConstr(u[start-1] == 1)

    # Constraints: each node has exactly one incoming and one outgoing edge
    for i in range(n):
        m.addConstr(gp.quicksum(x[i, j] for j in range(n) if j != i) == 1, name=f"outgoing_{i+1}")
        m.addConstr(gp.quicksum(x[j, i] for j in range(n) if j != i) == 1, name=f"incoming_{i+1}")

    # MTZ constraints to eliminate subtours (corrected version)
    for i in range(n):
        for j in range(n):
            if i != j and i != start-1 and j != start-1:
                m.addConstr(u[i] - u[j] + (n-1) * x[i, j] <= n-2, name=f"mtz_{i+1}_{j+1}")

    # Additional constraint for edges connected to start node
    for j in range(n):
        if j != start-1:
            m.addConstr(u[j] >= 2, name=f"u_min_{j+1}")
            m.addConstr(u[j] - u[start-1] + (n-1) * x[start-1, j] <= n-1, name=f"mtz_start_{j+1}")
            m.addConstr(u[start-1] - u[j] + (n-1) * x[j, start-1] <= n-1, name=f"mtz_{j+1}_start")

    # Objective: minimize total travel distance
    obj = gp.quicksum(dist[i][j] * x[i, j] for i in range(n) for j in range(n) if i != j)
    m.setObjective(obj, GRB.MINIMIZE)

    # Solve the model
    m.optimize()

    # Check solution status and display results
    if m.Status == GRB.OPTIMAL:
        print(f"Optimal solution found")
        print(f"Total distance: {m.ObjVal}")

        # Reconstruct the tour starting from location 1
        tour = [start]
        current = start - 1
        visited = set([current])

        while len(visited) < n:
            for j in range(n):
                if j != current and abs(x[current, j].X - 1.0) < 1e-6:
                    tour.append(j + 1)
                    current = j
                    visited.add(current)
                    break

        # Add return to start if not already included
        if tour[-1] != start:
            tour.append(start)

        print(f"Tour: {tour}")
    else:
        print(f"Optimization failed with status: {m.Status}")

except KeyError as e:
    print(f"Missing key in data dictionary: {e}")
except ValueError as e:
    print(f"Data validation error: {e}")
except gp.GurobiError as e:
    print(f"Gurobi error: {e}")
except Exception as e:
    print(f"Unexpected error: {e}")
